{
  "name": "loss_logsigmoid_000_cost_sum",
  "intuition": "rule_based: pairwise logsigmoid loss with sum aggregation",
  "pseudocode": "loss = sum(-logsigmoid(clamp(alpha*scale*(lpw-lpl) - 0.1*gap, -20, 20)) * weight)",
  "hyperparams": {
    "scale": 1.9496803035382082,
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "sum",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    x = alpha * scale * (lpw - lpl) - 0.1 * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return loss.sum()"
}

{
  "name": "pairwise_cost_gap_rank_loss",
  "intuition": "This loss encourages the model to prioritize sequences with lower cost gaps by maximizing the difference in log probabilities weighted by the cost gap. It directly aligns the model's preference with the cost-based ranking, promoting better preference modeling for RL4CO tasks.",
  "pseudocode": "loss = -mean_over_pairs(weight * (log_prob_w - log_prob_l)) where weight = sigmoid(-cost_gap)",
  "hyperparams": {
    "paradigm_family": "pairwise",
    "signal_family": "cost",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "ranking",
    "other_hparams": "None"
  },
  "operators_used": ["logsigmoid", "sigmoid", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = model_output['log_prob_w']\n    log_prob_l = model_output['log_prob_l']\n    cost_gap = batch.get('cost_gap', None)\n    weight = ops.sigmoid(ops.neg(cost_gap))\n    loss = -ops.mean(ops.mul(weight, ops.sub(log_prob_w, log_prob_l)))\n    return loss"
}

{
  "name": "loss_pairwise_ranknet_advantage_gap",
  "intuition": "Use a RankNet-style pairwise logistic loss but replace the input margin with the advantage gap signal, linking model preference to relative advantage differences.",
  "pseudocode": "score_diff = log_prob_w - log_prob_l\nadv_gap = advantage_w - advantage_l\ny = adv_gap.sign()\nloss = log(1 + exp(-y * score_diff)) weighted by weight\nreturn mean(loss)",
  "hyperparams": {
    "paradigm_family": "pairwise_logistic",
    "signal_family": "advantage_gap",
    "link_family": "logistic",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["sub", "sign", "exp", "log", "mul", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    score_diff = lpw - lpl\n    adv_gap = adv_w - adv_l\n    y = ops.sign(adv_gap)\n    # logistic loss: log(1 + exp(-y * score_diff))\n    loss = ops.log1p(ops.exp(-y * score_diff))\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()"
}

{
  "name": "loss_ranknet_advantage_exp",
  "intuition": "Use the RankNet paradigm with an exponential link on the advantage difference to emphasize stronger preferences, aggregating via weighted sum without clamping, shifting from margin-based to probabilistic preference modeling.",
  "pseudocode": "adv_diff = advantage_w - advantage_l\nprob = 1 / (1 + exp(-scale * adv_diff))\nloss = -weight * log(prob)\nreturn sum(loss) / sum(weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_probabilistic",
    "signal_family": "advantage_gap",
    "link_family": "sigmoid",
    "agg_family": "weighted_sum",
    "constraint_family": "none"
  },
  "operators_used": ["exp", "log", "div", "mul", "add", "sub", "sum"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    import torch\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    weight = batch.get('weight', torch.ones_like(adv_w))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    adv_diff = adv_w - adv_l\n    prob = 1 / (1 + torch.exp(-scale * adv_diff))\n    loss = -weight * torch.log(prob + 1e-12)\n    return loss.sum() / weight.sum()"
}

