    "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 2.1))\n    beta = float(extra.get('hyperparams', {}).get('beta', 0.05))\n    cost_gap = batch['cost_gap'].detach()\n    x = alpha * scale * (lpw - lpl) - beta * cost_gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss_per_pair = -ops.logsigmoid(x)\n    if weight is not None:\n        loss_per_pair = loss_per_pair * weight\n        total_weight = weight.sum() + 1e-8\n    else:\n        total_weight = lpw.new_tensor(lpw.shape[0], dtype=lpw.dtype).fill_(lpw.shape[0])\n    sum_loss = loss_per_pair.sum()\n    loss = sum_loss.sqrt() / total_weight\n    return loss"
