{
  "name": "pairwise_cost_gap_exp_logsigmoid",
  "intuition": "This loss applies an exponential scaling to the cost gap, emphasizing larger differences to improve gradient signals for significant cost variations. Using logsigmoid on the scaled difference enforces a smooth margin that encourages proper ranking while maintaining stability. The pairwise approach ensures direct comparison between candidate pairs, promoting relative preferences aligned with the cost gap.",
  "pseudocode": "gap_adj = exp(-scale * cost_gap)\nscore = alpha * (log_prob_w - log_prob_l) * gap_adj\nloss = -mean(logsigmoid(score), weights=weight)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "weighted_mean",
    "constraint_family": "clamp_stabilized",
    "other_hparams": "scale=1.5, alpha=1.0"
  },
  "operators_used": ["logsigmoid", "exp", "clamp", "mean"],
  "implementation_hint": {
