    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', 1.0))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.5))\n    cost_gap = batch['cost_gap'].detach()\n    gap_adj = ops.exp(-scale * cost_gap)\n    score = alpha * (lpw - lpl) * gap_adj\n    loss = -ops.logsigmoid(score)\n    if weight is not None:\n        loss = loss * weight\n        total_weight = weight.sum()\n    else:\n        total_weight = lpw.new_tensor(lpw.shape[0], dtype=lpw.dtype).fill_(lpw.shape[0])\n    return loss.sum() / (total_weight + 1e-8)"
}

