  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']  # shape (B, K)\n    gap_threshold = float(extra.get('gap_threshold', 0.2))\n    max_pairs = int(extra.get('max_pairs', 256))\n\n    # Compute pairwise differences\n    diff_obj = objective.unsqueeze(2) - objective.unsqueeze(1)  # shape (B, K, K)\n    # Mask for strictly better (lower) objective\n    strictly_better_mask = diff_obj < -gap_threshold  # shape (B, K, K)\n    # Remove pairs where difference is within threshold (negligible)\n    valid_mask = strictly_better_mask & (diff_obj.abs() > 1e-8)\n    # Flatten batch and pair dims\n    b_idx, winner_idx, loser_idx = valid_mask.nonzero(as_tuple=True)\n    # Cap number of pairs to max_pairs\n    total_pairs = b_idx.shape[0]\n    if total_pairs > max_pairs:\n        # Select top-k pairs based on the margin magnitude\n        margins = diff_obj[b_idx, winner_idx, loser_idx]\n        _, topk_indices = margins.abs().topk(max_pairs)\n        b_idx = b_idx[topk_indices]\n        winner_idx = winner_idx[topk_indices]\n        loser_idx = loser_idx[topk_indices]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'pairwise_cost_gap_mask_thresholded'})"
}

