{
  "name": "pairwise_dedup_topk_budget",
  "intuition": "Apply a per-instance top-k cap on pairwise preferences to limit the number of loser pairs per winner, focusing on the most meaningful strict preference pairs and enforcing a budget constraint.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "topk_per_anchor",
    "weight_family": "uniform_none",
    "constraint_family": "dedup_strict"
  },
  "operators_used": [
    "all_pairs",
    "lt",
    "masking",
    "topk"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    neq_mask = objective[:, :, None] != objective[:, None, :]\n    combined_mask = mask & neq_mask\n    bsz, n = objective.shape\n    # Generate scores to rank losers per winner\n    score_diff = objective[:, None, :] - objective[:, :, None]  # shape (bsz, n, n)\n    # We want topk losers per winner with smallest loser scores (i.e. largest diff)\n    # But only consider pairs in combined_mask\n    score_diff_masked = score_diff.clone()\n    score_diff_masked[~combined_mask] = float('-inf')\n    k = min(10, n)  # budget cap per winner\n    topk_vals, topk_idx = score_diff_masked.topk(k=k, dim=2)\n    # Build mask of winners and losers that are in topk\n    # For each batch and winner i, topk_idx[b,i,:] are loser indices\n    full_range = torch.arange(n, device=objective.device)\n    full_range = full_range.view(1, n, 1)\n    winner_idx = full_range.expand(bsz, n, k)\n    batch_idx = torch.arange(bsz, device=objective.device).view(bsz, 1, 1).expand(bsz, n, k)\n    selector_mask = torch.zeros_like(combined_mask, dtype=torch.bool)\n    selector_mask[batch_idx.flatten(), winner_idx.flatten(), topk_idx.flatten()] = True\n    filtered_mask = combined_mask & selector_mask\n    b_idx, winner_idx, loser_idx = filtered_mask.nonzero(as_tuple=True)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'pairwise_dedup_topk_budget'})"
}

