{
  "name": "builder_topk_pairs_dedup_002",
  "intuition": "Select top-k loser candidates per winner based on objective difference with explicit deduplication to limit pair count and focus on strongest preferences",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "topk_per_anchor",
    "weight_family": "uniform_none",
    "constraint_family": "dedup_explicit"
  },
  "operators_used": [
    "all_pairs",
    "neq",
    "masking",
    "topk"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    batch_size, n = objective.shape\n    # Compute mask for pairs where winner score < loser score and not equal\n    mask = objective[:, :, None] < objective[:, None, :]\n    diff_mask = objective[:, :, None] != objective[:, None, :]\n    combined_mask = mask & diff_mask\n    # Calculate score difference for sorting losers per winner\n    diff = (objective[:, None, :] - objective[:, :, None]).transpose(1, 2)  # shape [batch, winner, loser]\n    diff = diff * combined_mask.to(diff.dtype) - 1e9 * (~combined_mask)\n    # Top-k losers per winner, k fixed or from extra\n    k = extra.get('topk', 5)\n    topk_vals, topk_indices = diff.topk(k=min(k, n-1), dim=2)\n    winners_idx = torch.arange(n).view(1, n, 1).expand(batch_size, n, k).reshape(-1)\n    batch_idx = torch.arange(batch_size).view(batch_size, 1, 1).expand(batch_size, n, k).reshape(-1)\n    losers_idx = topk_indices.reshape(-1)\n    # Filter out invalid pairs (where topk_vals < -1e8 means no valid pair)\n    valid_mask = topk_vals.reshape(-1) > -1e8\n    b_idx = batch_idx[valid_mask]\n    w_idx = winners_idx[valid_mask]\n    l_idx = losers_idx[valid_mask]\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, w_idx, l_idx), weight=None, meta={'builder': 'topk_pairs_dedup'})"
}

