{
  "name": "builder_all_pairs_clamped_margin_001",
  "intuition": "all pairs with clamped margin to enforce stable and bounded preference gaps",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "clamped_margin",
    "weight_family": "uniform_none",
    "constraint_family": "clamp_explicit"
  },
  "operators_used": [
