  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Generate mask for pairs where winner score < loser score\n    mask = objective[:, :, None] < objective[:, None, :]\n    # Exclude pairs with equal scores to ensure strict preference\n    diff_mask = objective[:, :, None] != objective[:, None, :]\n    combined_mask = mask & diff_mask\n    b_idx, winner_idx, loser_idx = combined_mask.nonzero(as_tuple=True)\n    # Extract objective differences for clamping\n    obj_diff = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Clamp objective differences between 0.1 and 10 for stable margins\n    clamped_diff = obj_diff.clamp(min=0.1, max=10.0)\n    # Use clamped difference as weights to emphasize stable margins\n    weight = clamped_diff\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_clamped_margin'})"
